def transform(grid):
    h, w = len(grid), len(grid[0])
    # Paired panels around a solid separator: overlap is recolored 2.
    for i,row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != 0 and h-i-1 == i:
            return [[2 if a != 0 and b != 0 else 0 for a,b in zip(x,y)]
                    for x,y in zip(grid[:i],grid[i+1:])]
    for j in range(w):
        if all(r[j] == grid[0][j] != 0 for r in grid) and w-j-1 == j:
            return [[2 if a != 0 and b != 0 else 0 for a,b in zip(r[:j],r[j+1:])]
                    for r in grid]
    # In the compact case, treat columns as two masks and retain overlap.
    if w == 2:
        return [[2 if row[0] != 0 and row[1] != 0 else 0] for row in grid]
    raise ValueError('no separator')
